      "card_ids": ["C64","C70","C72","C73"]
    },
    {
      "claim": "L6 hepatic clearance records are mixed: low HLM intrinsic clearance for the morpholine-amide D703 (C83/C81) and human hepatocyte stability for the morpholine-amide SUVN-G3031 (C78) support limited hepatic first-pass loss, while high-CLint records (C76,C80,C84) involve less transferable structures or non-human assays and do not affirm F < 20% for the query.",
      "card_ids": ["C78","C81","C83","C76","C80","C84"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
